import { createAuthorizationURL } from "../oauth2/create-authorization-url.mjs";
import { refreshAccessToken } from "../oauth2/refresh-access-token.mjs";
import { validateAuthorizationCode } from "../oauth2/validate-authorization-code.mjs";
import { createRemoteJWKSet, decodeJwt } from "jose";
import { betterFetch } from "@better-fetch/fetch";
// src/social-providers/kakao.ts
const kakao = (options) => {
	const tokenEndpoint = "https://kauth.kakao.com/oauth/token";
	const getUserInfoFromProfile = async (profile) => {
		const userMap = await options.mapProfileToUser?.(profile);
		const account = profile.kakao_account || {};
		const kakaoProfile = account.profile || {};
		return {
			user: {
				name: kakaoProfile.nickname || account.name || "",
				email: account.email,
				image: kakaoProfile.profile_image_url || kakaoProfile.thumbnail_image_url,
				emailVerified: !!account.is_email_valid && !!account.is_email_verified,
				...userMap
			},
			data: profile
		};
	};
	return {
		id: "kakao",
		name: "Kakao",
		accountSubject: ({ profile }) => profile.id,
		createAuthorizationURL({ state, scopes, codeVerifier, redirectURI, loginHint, additionalParams }) {
			const _scopes = options.disableDefaultScope ? [] : [
				"account_email",
				"profile_image",
				"profile_nickname"
			];
			if (options.scope) _scopes.push(...options.scope);
			if (scopes) _scopes.push(...scopes);
			return createAuthorizationURL({
				id: "kakao",
				options,
				authorizationEndpoint: "https://kauth.kakao.com/oauth/authorize",
				scopes: _scopes,
				state,
				codeVerifier,
				redirectURI,
				loginHint,
				additionalParams
			});
		},
		validateAuthorizationCode: async ({ code, codeVerifier, redirectURI }) => {
			return validateAuthorizationCode({
				code,
				codeVerifier,
				redirectURI,
				options,
				tokenEndpoint
			});
		},
		refreshAccessToken: options.refreshAccessToken ? options.refreshAccessToken : async (refreshToken) => {
			return refreshAccessToken({
				refreshToken,
				options: {
					clientId: options.clientId,
					clientKey: options.clientKey,
					clientSecret: options.clientSecret
				},
				tokenEndpoint
			});
		},
		idToken: {
			jwks: createRemoteJWKSet(new URL("https://kauth.kakao.com/.well-known/jwks.json")),
			issuer: "https://kauth.kakao.com",
			audience: options.clientId,
			algorithms: ["RS256"]
		},
		async getUserInfoFromIdToken(idToken) {
			if (options.getUserInfo) return options.getUserInfo({ idToken });
			const claims = decodeJwt(idToken);
			return getUserInfoFromProfile({
				id: Number(claims.sub),
				kakao_account: {
					email: claims.email,
					profile: {
						nickname: claims.nickname,
						thumbnail_image_url: claims.picture
					}
				}
			});
		},
		async getUserInfo(token) {
			if (options.getUserInfo) return options.getUserInfo(token);
			const { data: profile, error } = await betterFetch("https://kapi.kakao.com/v2/user/me", { headers: { Authorization: `Bearer ${token.accessToken}` } });
			if (error || !profile) return null;
			return getUserInfoFromProfile(profile);
		},
		options
	};
};
export { kakao };
